#include <string>
#include <vector>
#include <cmath>

class Solution {
public:
    std::string reformat(std::string s) {
        std::string letters = "", digits = "";
        for (char c : s) {
            if (std::isdigit(c)) digits += c;
            else letters += c;
        }
        if (std::abs((int)letters.size() - (int)digits.size()) > 1) return "";
        std::string first = letters.size() >= digits.size() ? letters : digits;
        std::string second = letters.size() >= digits.size() ? digits : letters;
        std::string res = "";
        for (int i = 0; i < (int)first.size(); ++i) {
            res += first[i];
            if (i < (int)second.size()) res += second[i];
        }
        return res;
    }
};

class Solution {
    public String reformat(String s) {
        StringBuilder letters = new StringBuilder();
        StringBuilder digits = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) digits.append(c);
            else letters.append(c);
        }
        if (Math.abs(letters.length() - digits.length()) > 1) return "";
        StringBuilder first = letters.length() >= digits.length() ? letters : digits;
        StringBuilder second = letters.length() >= digits.length() ? digits : letters;
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < first.length(); i++) {
            res.append(first.charAt(i));
            if (i < second.length()) res.append(second.charAt(i));
        }
        return res.toString();
    }
}

var reformat = function(s) {
    const letters = [];
    const digits = [];
    for (const c of s) {
        if (c >= '0' && c <= '9') digits.push(c);
        else letters.push(c);
    }
    if (Math.abs(letters.length - digits.length) > 1) return "";
    const first = letters.length >= digits.length ? letters : digits;
    const second = letters.length >= digits.length ? digits : letters;
    const res = [];
    for (let i = 0; i < first.length; i++) {
        res.push(first[i]);
        if (i < second.length) res.push(second[i]);
    }
    return res.join('');
};
